def transform_simple(grid):
    """Copy pattern from cols 5-8 to separator at same cols, 8 at grid int, clear rest"""
    rows = len(grid)
    cols = len(grid[0])
    output = [list(r) for r in grid]

    # Extract pattern from input rows 0-3, cols 5-8
    pattern_rows = []
    for r in range(0, 4):
        pat = grid[r][5:9]
        pattern_rows.append(list(pat))

    # Add 8s at grid intersections based on INPUT (not output)
    for r in range(rows):
        for c in range(cols):
            if r % 6 == 0 and c % 6 == 0:
                if grid[r][c] != 0:
                    output[r][c] = 8

    # Clear the separator region first
    for r in range(5, 9):
        output[r] = [0]*cols

    # Copy pattern to separator region rows 5-8 at cols 5-8
    offset = 5
    for src_r, tgt_r in enumerate(range(5, 9)):
        pattern = pattern_rows[src_r]
        out_row = output[tgt_r]
        for c in range(4):
            out_row[c + offset] = pattern[c]

    return output

